# Run from the package directory:
# Rscript data-raw/approximation-bias/run_approximation_bias.R <output-dir> [cores=1] [source-dir=.]
# Requires pkgload. Supports the approximation sizes quoted in the help of getSimData(), getLCSM() and
# getTVCmodel(): one data set of 5,000 persons per model, generated by getSimData() with its default values
# (ten yearly occasions, seed 2026), is fitted by the matching model. Each data set is also rebuilt so that
# the curves follow the construction the fitted model assumes, which isolates the cause of a bias:
#   exact            the growth curve at each person's own growth factors, as getSimData() generates it;
#   taylor           the curve expanded to first order in the growth ratio or knot around its mean, as a
#                    model with a random ratio or knot is fitted;
#   midpoint         each interval's change as the rate at its midpoint times its length, as a latent change
#                    score model integrates its rates (rates at each person's own ratio);
#   midpoint_taylor  both: the construction a latent change score model with a random ratio assumes.
# Growth factors and residuals are the same in all arms of a model. One data set per model gives a single
# estimate with its standard error, not a replicated bias or coverage study.
args <- commandArgs(trailingOnly = TRUE)
if (length(args) < 1L || length(args) > 3L) stop("Usage: output-dir [cores=1] [source-dir=.]")
out_dir <- args[1]
cores <- if (length(args) >= 2L) as.integer(args[2]) else 1L
source_dir <- normalizePath(if (length(args) >= 3L) args[3] else ".", mustWork = TRUE)
if (!is.finite(cores) || cores < 1L) stop("cores must be a positive integer")
if (dir.exists(out_dir) && length(list.files(out_dir, all.files = TRUE, no.. = TRUE))) {
  stop("Use a new or empty output directory to preserve earlier evidence")
}
dir.create(out_dir, recursive = TRUE, showWarnings = FALSE)
out_dir <- normalizePath(out_dir, mustWork = TRUE)
pkgload::load_all(source_dir, quiet = TRUE)
OpenMx::mxOption(NULL, "Default optimizer", "CSOLNP")
OpenMx::mxOption(NULL, "Number of Threads", 1L)
Sys.setenv(OMP_NUM_THREADS = "1", OPENBLAS_NUM_THREADS = "1")
n <- 5000L; seed <- 2026L; fit_seed <- 20191029L

models <- list(
  # no approximation: controls
  LGCM_LIN = list(fit = "LGCM", curveFun = "LIN", intrinsic = FALSE, arms = "exact"),
  LGCM_QUAD = list(fit = "LGCM", curveFun = "QUAD", intrinsic = FALSE, arms = "exact"),
  LGCM_EXP_f = list(fit = "LGCM", curveFun = "EXP", intrinsic = FALSE, arms = "exact"),
  LCSM_QUAD = list(fit = "LCSM", curveFun = "QUAD", intrinsic = FALSE, arms = "exact"),
  TVC_d3_EXP_f = list(fit = "TVC", curveFun = "EXP", intrinsic = FALSE, decompose = 3, arms = "exact"),
  # first-order Taylor expansion in a random ratio or knot
  LGCM_EXP_r = list(fit = "LGCM", curveFun = "EXP", intrinsic = TRUE, arms = c("exact", "taylor")),
  LGCM_JB_r = list(fit = "LGCM", curveFun = "JB", intrinsic = TRUE, arms = c("exact", "taylor")),
  LGCM_BLS_r = list(fit = "LGCM", curveFun = "BLS", intrinsic = TRUE, arms = c("exact", "taylor")),
  MGM_EXP_r = list(fit = "MGM", curveFun = "EXP", intrinsic = TRUE, arms = c("exact", "taylor")),
  TVC_d1_EXP_r = list(fit = "TVC", curveFun = "EXP", intrinsic = TRUE, decompose = 1, arms = c("exact", "taylor")),
  TVC_d3_EXP_r = list(fit = "TVC", curveFun = "EXP", intrinsic = TRUE, decompose = 3, arms = c("exact", "taylor")),
  # midpoint rates of a latent change score model, with and without a random ratio
  LCSM_EXP_f = list(fit = "LCSM", curveFun = "EXP", intrinsic = FALSE, arms = c("exact", "midpoint")),
  LCSM_JB_f = list(fit = "LCSM", curveFun = "JB", intrinsic = FALSE, arms = c("exact", "midpoint")),
  LCSM_EXP_r = list(fit = "LCSM", curveFun = "EXP", intrinsic = TRUE, arms = c("exact", "taylor", "midpoint", "midpoint_taylor")),
  LCSM_JB_r = list(fit = "LCSM", curveFun = "JB", intrinsic = TRUE, arms = c("exact", "taylor", "midpoint", "midpoint_taylor")))

# Rate of a negative exponential or Jenss-Bayley curve at times t, at each person's ratio g.
rate <- function(form, g, t, gamma) {
  if (form == "EXP") g[, "eta1"] * gamma * exp(-gamma * t) else g[, "eta1"] + g[, "eta2"] * gamma * exp(gamma * t)
}
# Its first-order expansion in the ratio around the mean m (the rate loadings of a random-ratio LCSM).
rate_taylor <- function(form, g, t, m) {
  mug <- m[["gamma"]]
  if (form == "EXP") g[, "eta1"] * mug * exp(-mug * t) + (g[, "gamma"] - mug) * m[["eta1"]] * exp(-mug * t) * (1 - mug * t) else
    g[, "eta1"] + g[, "eta2"] * mug * exp(mug * t) + (g[, "gamma"] - mug) * m[["eta2"]] * (1 + mug * t) * exp(mug * t)
}
# The curve expanded to first order in the ratio or knot around the mean m, as the fitted model describes it.
curve_taylor <- function(form, g, occ, m) {
  mug <- m[["gamma"]]
  if (form == "BLS") {  # nlpsem's form: status at the knot, mid-slope and half-difference, expanded in the knot
    e0s <- g[, "eta0"] + g[, "eta1"] * g[, "gamma"]; e1s <- (g[, "eta1"] + g[, "eta2"]) / 2; e2s <- (g[, "eta2"] - g[, "eta1"]) / 2
    m1s <- (m[["eta1"]] + m[["eta2"]]) / 2; m2s <- (m[["eta2"]] - m[["eta1"]]) / 2; dt <- occ - mug
    return(e0s + e1s * dt + e2s * abs(dt) + (g[, "gamma"] - mug) * (-m1s - m2s * sign(dt)))
  }
  g0 <- g; g0[, "gamma"] <- mug
  gm <- matrix(m[colnames(g)], nrow(g), ncol(g), byrow = TRUE, dimnames = list(NULL, colnames(g)))
  h <- 1e-5; gp <- gm; gp[, "gamma"] <- mug + h; gn <- gm; gn[, "gamma"] <- mug - h
  nlpsem:::.sim_curve(form, g0, occ, NULL) +
    (g[, "gamma"] - mug) * (nlpsem:::.sim_curve(form, gp, occ, NULL) - nlpsem:::.sim_curve(form, gn, occ, NULL)) / (2 * h)
}
# Replace each outcome's exact curve by the curve of the arm; residuals and growth factors are kept.
rebuild <- function(d, model, arm) {
  if (arm == "exact") return(d)
  s <- attr(d, "settings"); p <- s$params[[1]]; gf <- attr(d, "growth_factors"); nT <- s$nT
  occ <- as.matrix(d[paste0("T", seq_len(nT))])
  for (k in seq_along(s$y_var)) {
    pre <- if (model$fit %in% c("MGM", "TVC")) paste0(if (model$fit == "TVC") "Y" else s$y_var[k], "_") else ""
    g <- if (pre == "") gf else { x <- gf[, startsWith(colnames(gf), pre), drop = FALSE]; colnames(x) <- sub(pre, "", colnames(x), fixed = TRUE); x }
    m <- if (model$fit == "MGM") p$mean[[k]] else p$mean
    cols <- paste0(s$y_var[k], seq_len(nT))
    exact <- nlpsem:::.sim_curve(model$curveFun, g, occ, NULL)
    built <- if (arm == "taylor") curve_taylor(model$curveFun, g, occ, m) else {
      mid <- (occ[, -1] + occ[, -nT]) / 2; lag <- occ[, -1] - occ[, -nT]
      r <- if (arm == "midpoint") rate(model$curveFun, g, mid, g[, "gamma"]) else rate_taylor(model$curveFun, g, mid, m)
      g[, "eta0"] + cbind(0, t(apply(r * lag, 1, cumsum)))
    }
    d[cols] <- as.matrix(d[cols]) - exact + built
  }
  d
}
run_one <- function(job) {
  model <- models[[job$model]]; arm <- job$arm; started <- proc.time()[[3]]
  sim <- list(n = n, curveFun = model$curveFun, intrinsic = model$intrinsic, seed = seed)
  if (model$fit == "MGM") sim$sub_Model <- "MGM"
  if (model$fit == "TVC") { sim$sub_Model <- "TVC"; sim$decompose <- model$decompose }
  d <- rebuild(do.call(getSimData, sim), model, arm)
  set.seed(fit_seed)
  common <- list(dat = d, curveFun = model$curveFun, intrinsic = model$intrinsic, tries = 3, paramOut = TRUE)
  fit <- tryCatch(suppressWarnings(suppressMessages(switch(model$fit,
    LGCM = do.call(getLGCM, c(common, list(t_var = "T", y_var = "Y", records = 1:10))),
    LCSM = do.call(getLCSM, c(common, list(t_var = "T", y_var = "Y", records = 1:10))),
    MGM = do.call(getMGM, c(common, list(t_var = c("T", "T"), y_var = c("Y", "Z"), records = list(1:10, 1:10), y_model = "LGCM"))),
    TVC = do.call(getTVCmodel, c(common, list(t_var = "T", y_var = "Y", records = 1:10, y_model = "LGCM", TVC = "TVC",
                                               decompose = model$decompose)))))), error = identity)
  truth <- attr(d, "truth")
  if (inherits(fit, "error")) {
    return(list(fit = data.frame(model = job$model, arm = arm, status = NA, issues = conditionMessage(fit), hessian = NA,
                                 se_available = NA, se_expected = NA, minus2LL = NA, seconds = proc.time()[[3]] - started),
                estimates = NULL))
  }
  dg <- getDiagnostics(fit); e <- fit@Estimates[match(names(truth), fit@Estimates$Name), ]
  est <- data.frame(model = job$model, arm = arm, name = names(truth), truth = unname(truth), estimate = e$Estimate, se = e$SE)
  est$z <- (est$estimate - est$truth) / est$se
  est$relative_bias <- ifelse(est$truth == 0, NA, (est$estimate - est$truth) / abs(est$truth))
  list(fit = data.frame(model = job$model, arm = arm, status = fit@mxOutput@output$status$code,
                        issues = paste(dg$issues, collapse = "; "), hessian = dg$hessian$status,
                        se_available = dg$standard_errors$available, se_expected = dg$standard_errors$expected,
                        minus2LL = fit@mxOutput@output$Minus2LogLikelihood, seconds = proc.time()[[3]] - started),
       estimates = est)
}
jobs <- do.call(c, lapply(names(models), function(m) lapply(models[[m]]$arms, function(a) list(model = m, arm = a))))
# the slowest fits (TVC) first
jobs <- jobs[order(!vapply(jobs, function(j) models[[j$model]]$fit == "TVC", logical(1)))]
started <- Sys.time()
results <- if (cores > 1L) parallel::mclapply(jobs, run_one, mc.cores = cores, mc.preschedule = FALSE) else lapply(jobs, run_one)
failed <- vapply(results, inherits, logical(1), "try-error")
if (any(failed)) stop("Workers failed: ", paste(vapply(jobs[failed], function(j) paste(j$model, j$arm), ""), collapse = ", "))
fits <- do.call(rbind, lapply(results, `[[`, "fit")); estimates <- do.call(rbind, lapply(results, `[[`, "estimates"))
utils::write.csv(fits, file.path(out_dir, "fits.csv"), row.names = FALSE)
utils::write.csv(estimates, file.path(out_dir, "estimates.csv"), row.names = FALSE)
git <- function(...) tryCatch(system2("git", c("-C", shQuote(source_dir), ...), stdout = TRUE, stderr = FALSE), error = function(e) NA)
writeLines(c(paste("commit:", git("rev-parse", "HEAD")),
             paste("uncommitted changes:", length(git("status", "--porcelain")) > 0),
             paste("nlpsem:", read.dcf(file.path(source_dir, "DESCRIPTION"), fields = "Version")[1, 1]),
             paste("R:", R.version.string), paste("OpenMx:", as.character(utils::packageVersion("OpenMx"))),
             paste("platform:", R.version$platform), paste("persons per data set:", n), paste("data seed:", seed),
             paste("fitting seed:", fit_seed), "optimizer: CSOLNP, tries = 3, one thread",
             paste("started:", format(started, tz = "UTC", usetz = TRUE)), paste("finished:", format(Sys.time(), tz = "UTC", usetz = TRUE))),
           file.path(out_dir, "run-info.txt"))
cat("fits:", nrow(fits), "| status 0:", sum(fits$status == 0, na.rm = TRUE), "| without diagnostic issues:", sum(fits$issues == "", na.rm = TRUE), "\n")
